/* School Dashboard - scope .page-content */
.page-wrapper .page-content {
    --sch-primary: #4b6c9e;
    --sch-primary-light: #6b8bb8;
    --sch-primary-subtle: rgba(75, 108, 158, 0.12);
    --sch-success: #2e9e6e;
    --sch-danger: #d9534f;
    --sch-warning: #e8a838;
    --sch-info: #5b9bd5;
    --sch-card-radius: 12px;
    --sch-card-shadow: 0 2px 12px rgba(75, 108, 158, 0.08);
    --sch-card-shadow-hover: 0 8px 24px rgba(75, 108, 158, 0.14);
    --sch-text-muted: #6c7a89;
    --sch-border: #e8ecf1;
}

.page-wrapper .page-content .sch-dash-card {
    border: 1px solid var(--sch-border);
    border-radius: var(--sch-card-radius);
    box-shadow: var(--sch-card-shadow);
    background: #fff;
    transition: box-shadow 0.25s ease, transform 0.25s ease;
}

.page-wrapper .page-content .sch-dash-card:hover {
    box-shadow: var(--sch-card-shadow-hover);
}

.page-wrapper .page-content .sch-dash-card-header {
    padding: 1rem 1.25rem 0.5rem;
    border-bottom: none;
    background: transparent;
}

.page-wrapper .page-content .sch-dash-card-header h5 {
    font-size: 0.95rem;
    font-weight: 600;
    color: #2c3e50;
    margin: 0;
}

.page-wrapper .page-content .sch-dash-card-body {
    padding: 0.75rem 1.25rem 1.25rem;
}

/* Filter bar */
.page-wrapper .page-content .sch-dash-filter {
    padding: 1rem 1.25rem;
    margin-bottom: 1.25rem;
}

.page-wrapper .page-content .sch-dash-filter label {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--sch-text-muted);
    margin-bottom: 0.25rem;
}

.page-wrapper .page-content .sch-dash-filter .form-select {
    font-size: 0.85rem;
    border-color: var(--sch-border);
    border-radius: 8px;
    padding: 0.4rem 2rem 0.4rem 0.75rem;
    color: #2c3e50;
}

.page-wrapper .page-content .sch-dash-filter .form-select:focus {
    border-color: var(--sch-primary);
    box-shadow: 0 0 0 0.2rem rgba(75, 108, 158, 0.15);
}

.page-wrapper .page-content .sch-dash-update {
    font-size: 0.8rem;
    color: var(--sch-text-muted);
}

.page-wrapper .page-content .sch-dash-update strong {
    color: #2c3e50;
}

.page-wrapper .page-content .btn-sch-refresh {
    background: var(--sch-primary);
    border-color: var(--sch-primary);
    color: #fff;
    border-radius: 8px;
    font-size: 0.85rem;
    padding: 0.45rem 1rem;
    transition: background 0.2s ease;
}

.page-wrapper .page-content .btn-sch-refresh:hover {
    background: #3d5a82;
    border-color: #3d5a82;
    color: #fff;
}

.page-wrapper .page-content .btn-sch-refresh .bi {
    transition: transform 0.4s ease;
}

.page-wrapper .page-content .btn-sch-refresh.is-loading .bi {
    animation: sch-dash-spin 0.8s linear infinite;
}

@keyframes sch-dash-spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

/* KPI cards */
.page-wrapper .page-content .sch-dash-kpi {
    padding: 1.15rem 1.25rem;
    height: 100%;
    cursor: default;
}

.page-wrapper .page-content .sch-dash-kpi:hover {
    transform: translateY(-3px);
}

.page-wrapper .page-content .sch-dash-kpi-icon {
    width: 48px;
    height: 48px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.35rem;
    flex-shrink: 0;
}

.page-wrapper .page-content .sch-dash-kpi-icon.primary { background: var(--sch-primary-subtle); color: var(--sch-primary); }
.page-wrapper .page-content .sch-dash-kpi-icon.success { background: rgba(46, 158, 110, 0.12); color: var(--sch-success); }
.page-wrapper .page-content .sch-dash-kpi-icon.warning { background: rgba(232, 168, 56, 0.12); color: var(--sch-warning); }
.page-wrapper .page-content .sch-dash-kpi-icon.danger { background: rgba(217, 83, 79, 0.12); color: var(--sch-danger); }
.page-wrapper .page-content .sch-dash-kpi-icon.info { background: rgba(91, 155, 213, 0.12); color: var(--sch-info); }

.page-wrapper .page-content .sch-dash-kpi-value {
    font-size: 1.65rem;
    font-weight: 700;
    color: #2c3e50;
    line-height: 1.2;
}

.page-wrapper .page-content .sch-dash-kpi-label {
    font-size: 0.78rem;
    color: var(--sch-text-muted);
    font-weight: 500;
    margin-top: 0.15rem;
}

.page-wrapper .page-content .sch-dash-kpi-trend {
    font-size: 0.75rem;
    font-weight: 600;
    margin-top: 0.5rem;
}

.page-wrapper .page-content .sch-dash-kpi-trend.up { color: var(--sch-success); }
.page-wrapper .page-content .sch-dash-kpi-trend.down { color: var(--sch-danger); }
.page-wrapper .page-content .sch-dash-kpi-trend.neutral { color: var(--sch-text-muted); }

/* Chart cards */
.page-wrapper .page-content .sch-dash-chart-wrap {
    min-height: 320px;
    overflow: hidden;
}

.page-wrapper .page-content .sch-dash-chart-wrap > div {
    width: 100%;
    max-width: 100%;
}

.page-wrapper .page-content .sch-dash-chart-wrap.sm {
    min-height: 280px;
}

/* Alert timeline */
.page-wrapper .page-content .sch-dash-alerts {
    padding: 1.25rem;
}

.page-wrapper .page-content .sch-dash-alerts-title {
    font-size: 1rem;
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 1rem;
}

.page-wrapper .page-content .sch-dash-alert-item {
    display: flex;
    align-items: flex-start;
    gap: 0.85rem;
    padding: 0.85rem 1rem;
    border-radius: 10px;
    margin-bottom: 0.65rem;
    border-left: 4px solid transparent;
    transition: background 0.2s ease;
}

.page-wrapper .page-content .sch-dash-alert-item:last-child {
    margin-bottom: 0;
}

.page-wrapper .page-content .sch-dash-alert-item:hover {
    filter: brightness(0.98);
}

.page-wrapper .page-content .sch-dash-alert-item.danger {
    background: rgba(217, 83, 79, 0.08);
    border-left-color: var(--sch-danger);
}

.page-wrapper .page-content .sch-dash-alert-item.warning {
    background: rgba(232, 168, 56, 0.1);
    border-left-color: var(--sch-warning);
}

.page-wrapper .page-content .sch-dash-alert-icon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
    flex-shrink: 0;
}

.page-wrapper .page-content .sch-dash-alert-item.danger .sch-dash-alert-icon {
    background: rgba(217, 83, 79, 0.15);
    color: var(--sch-danger);
}

.page-wrapper .page-content .sch-dash-alert-item.warning .sch-dash-alert-icon {
    background: rgba(232, 168, 56, 0.2);
    color: #c48a1a;
}

.page-wrapper .page-content .sch-dash-alert-text {
    font-size: 0.88rem;
    color: #2c3e50;
    font-weight: 500;
    line-height: 1.4;
}

.page-wrapper .page-content .sch-dash-alert-meta {
    font-size: 0.75rem;
    color: var(--sch-text-muted);
    margin-top: 0.15rem;
}

/* AI Insight */
.page-wrapper .page-content .sch-dash-insight {
    padding: 1.25rem;
    background: linear-gradient(135deg, #f8fafc 0%, #eef2f7 100%);
    border: 1px solid var(--sch-border);
}

.page-wrapper .page-content .sch-dash-insight-header {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    margin-bottom: 1rem;
}

.page-wrapper .page-content .sch-dash-insight-avatar {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--sch-primary) 0%, var(--sch-primary-light) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-size: 1.1rem;
}

.page-wrapper .page-content .sch-dash-insight-header h5 {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    color: #2c3e50;
}

.page-wrapper .page-content .sch-dash-insight-header small {
    color: var(--sch-text-muted);
    font-size: 0.75rem;
}

.page-wrapper .page-content .sch-dash-insight-item {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    padding: 0.75rem 1rem;
    background: #fff;
    border-radius: 10px;
    margin-bottom: 0.55rem;
    border: 1px solid var(--sch-border);
    font-size: 0.88rem;
    color: #3d4f5f;
    line-height: 1.45;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.page-wrapper .page-content .sch-dash-insight-item:hover {
    border-color: var(--sch-primary-light);
    box-shadow: 0 2px 8px rgba(75, 108, 158, 0.1);
}

.page-wrapper .page-content .sch-dash-insight-item:last-child {
    margin-bottom: 0;
}

.page-wrapper .page-content .sch-dash-insight-item .insight-emoji {
    font-size: 1rem;
    flex-shrink: 0;
    margin-top: 1px;
}

/* Spacing */
.page-wrapper .page-content .sch-dash-row {
    margin-bottom: 1.25rem;
}

.page-wrapper .page-content .sch-dash-kpi-col {
    margin-bottom: 1rem;
